from __future__ import annotations

import ast
import hashlib
import subprocess
import sys
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent


def locate_repository() -> Path:
    candidates = []
    for base in (Path.cwd().resolve(), SCRIPT_DIR):
        candidates.extend((base, base / "kalshi-qss-bot"))
        for parent in base.parents:
            candidates.extend((parent, parent / "kalshi-qss-bot"))
    seen = set()
    for candidate in candidates:
        candidate = candidate.resolve()
        if candidate in seen:
            continue
        seen.add(candidate)
        if (
            candidate / "qseries_v2" / "oracle_terminal"
            / "oracle_genuine_intelligence_artifact_admission.py"
        ).is_file():
            return candidate
    raise SystemExit("[ERROR] Could not locate repository containing OIT-005.")


ROOT = locate_repository()
PACKAGE = ROOT / "qseries_v2" / "oracle_terminal"
OIT_003 = PACKAGE / "oracle_live_intelligence_activation_discovery.py"
OIT_004 = PACKAGE / "oracle_bounded_live_intelligence_activation.py"
